static partial class Curriculum
{
    private static readonly VersionStamp TailwindDocs = new("Tailwind CSS", "v4 · Vite · CSS-first configuration", "2026-10-12", "https://tailwindcss.com/docs/installation/using-vite");
    public static Lesson[] BuildTailwindLessons() => NormalizeLessons(
    [
        new("tailwind-01", "Introduction", 1, "What Tailwind CSS actually is", "A utility-first CSS framework supplies small, single-purpose classes that compile into ordinary CSS.", "CSS styles HTML elements. A utility class maps to a narrow declaration: p-4 adds padding, rounded-lg rounds corners, and font-semibold sets font weight. Tailwind scans source files for complete class names and generates the CSS needed by the build. It is not a React framework and does not add JavaScript behavior.", "<article class=\"rounded-lg border p-4\"><h1 class=\"text-xl font-semibold\">Pathway</h1></article>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-02", "Introduction", 2, "Strengths, weaknesses, and tradeoffs", "Understand where Tailwind helps and where plain CSS or components work better.", "Strengths: consistent spacing and color scales, quick iteration without inventing class names, responsive/state variants, CSS output without a runtime styling engine, and easy design-token reuse. Weaknesses: noisy markup, a learning curve for utility names, repetitive class combinations, awkward dynamic class construction, and shared components that still need disciplined ownership. CSS knowledge remains essential; Tailwind does not solve accessibility, architecture, or design decisions.", "Strength: <button class=\"px-4 py-2 rounded-md\">Continue</button> | Tradeoff: long className strings can obscure component meaning.", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-03", "Introduction", 3, "Why choose Tailwind instead of other CSS approaches?", "Use an explicit decision framework rather than treating a framework as automatically better.", "Plain CSS is great for small sites and unique complex selectors; CSS Modules scope authored styles to components; Tailwind is especially effective for repeated application UI patterns with a shared design system. Component libraries can provide behavior and accessibility on top of any styling approach. Tailwind accelerates expressing CSS but not choosing good layouts. For Pathway, reusable lesson cards, navigation, badges and buttons make utilities and design tokens useful.", "Choose Tailwind for consistent repeated UI; choose custom CSS for unusual animations, selectors, and semantic site-wide rules.", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-04", "Installation", 4, "Prerequisites and create a starter project", "Set up Node.js, npm, a terminal, and an editor before touching the framework.", "Install an active Node.js LTS version from https://nodejs.org and use npm, which ships with Node. In a terminal, check node --version and npm --version. Use an editor such as https://code.visualstudio.com. Vite is a frontend development server and build tool. Run the commands in sequence; the react-ts template includes React and TypeScript but Tailwind also works with plain HTML.", "node --version\nnpm --version\nnpm create vite@latest pathway-tailwind -- --template react-ts\ncd pathway-tailwind\nnpm install", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-05", "Installation", 5, "Configure Tailwind CSS v4 with Vite", "Use the current CSS-first integration, not legacy v3 setup commands.", "Install tailwindcss and @tailwindcss/vite. In vite.config.ts import tailwindcss from @tailwindcss/vite, and include tailwindcss() alongside react() in plugins. In src/index.css add @import \"tailwindcss\"; then ensure main.tsx imports ./index.css. Run npm run dev and verify utilities in browser DevTools. Do not follow legacy tailwindcss init -p or @tailwind base/components/utilities directions for this setup.", "npm install tailwindcss @tailwindcss/vite\n// vite.config.ts\nimport { defineConfig } from 'vite'\nimport react from '@vitejs/plugin-react'\nimport tailwindcss from '@tailwindcss/vite'\nexport default defineConfig({ plugins: [react(), tailwindcss()] })\n/* src/index.css */\n@import \"tailwindcss\";\nnpm run dev", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-06", "Basic concepts", 6, "Utilities and the CSS box model", "Learn which real CSS declarations Tailwind utilities represent.", "Each box has content, padding, border, and margin. p-4 sets padding inside the border, m-4 sets margin outside it, border adds a border, and box-border uses border-box sizing. Numeric spacing utilities refer to the theme spacing scale; they are not literal pixels. Inspect computed CSS to confirm the actual output. Prefer gap between flex/grid children instead of manually giving each child margin.", "<div class=\"m-4 border p-4\"><p class=\"mb-2\">Lesson notes</p><p class=\"text-sm\">Spacing matters.</p></div>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-07", "Basic concepts", 7, "Typography, colors, borders and surfaces", "Create readable, consistent text and visual hierarchy.", "text-sm changes font size, font-semibold changes weight, leading-relaxed adjusts line height, tracking-wide adjusts letter spacing, text-slate-700 sets foreground and bg-white sets background. rounded-xl and shadow-sm describe card surfaces. Color alone must not communicate status; check contrast. Tailwind Preflight resets browser defaults, so restore desired heading/list styles explicitly.", "<section class=\"rounded-xl border border-slate-200 bg-white p-6 shadow-sm\"><h2 class=\"text-xl font-semibold text-slate-900\">Lesson</h2><p class=\"mt-2 text-sm leading-relaxed text-slate-600\">Learn before testing.</p></section>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-08", "Basic layout", 8, "Display, sizing, and document flow", "Control element size before reaching for elaborate page layouts.", "Block elements usually begin on a new line; inline elements participate in text; inline-flex and flex create a flex formatting context. Use w-full for available width, max-w-4xl for a readable maximum, mx-auto to center a block, min-h-screen for viewport-sized shells, and overflow-auto when content needs a scroll container. Avoid fixed heights for prose that can wrap.", "<main class=\"mx-auto min-h-screen w-full max-w-4xl px-4 py-8\">Readable content column</main>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-09", "Basic layout", 9, "Flexbox for navigation and controls", "Arrange items along one primary axis, including wrapping and alignment.", "flex creates a flex container; flex-col makes it vertical; items-center aligns the cross axis; justify-between distributes extra space on the main axis; gap-3 separates children. Use flex-wrap when labels or buttons may not fit. flex-1 allows a content area to consume remaining space, and min-w-0 lets it shrink without overflow.", "<header class=\"flex flex-wrap items-center justify-between gap-3\"><span>Pathway</span><nav class=\"flex items-center gap-3\">Courses · Progress</nav></header>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-10", "Basic layout", 10, "Grid for the Pathway application shell", "Use grid tracks for sidebars and main content.", "Grid is ideal when two-dimensional structure matters. grid-cols-1 stacks tracks; md:grid-cols-[16rem_minmax(0,1fr)] creates a sidebar and flexible content on wider screens. minmax(0,1fr) allows the content area to shrink properly. The sidebar can collapse or be hidden on small screens, but navigation must remain operable.", "<div class=\"grid min-h-screen grid-cols-1 md:grid-cols-[16rem_minmax(0,1fr)]\"><aside class=\"border-r p-4\">Courses</aside><main class=\"min-w-0 p-6\">Lesson</main></div>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-11", "Utilities", 11, "Responsive utilities and mobile-first thinking", "Make narrow layouts the default and progressively enhance available space.", "Unprefixed utilities apply at every width. md: utilities apply at the medium breakpoint and larger; they do not mean 'only tablets'. Start with stacked content and add larger layouts when space warrants. Test narrow browsers and zoom, not just device presets. Container queries respond to parent width rather than viewport width; use them for reusable cards with varying containers.", "<div class=\"grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3\">...</div>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-12", "Utilities", 12, "Pseudo-states, focus and accessible controls", "Use variant prefixes to respond to meaningful states.", "hover: changes styles under pointer hover; focus-visible: presents keyboard focus; disabled: handles disabled controls. Combine variants with utilities, e.g. focus-visible:outline-2. A visual focus indicator and native button semantics are mandatory for accessible keyboard interactions. Use aria-* variants when UI state already exists in semantic attributes.", "<button class=\"rounded-lg bg-emerald-700 px-4 py-2 text-white hover:bg-emerald-800 focus-visible:outline-2 focus-visible:outline-offset-2 disabled:opacity-50\">Continue</button>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-13", "Utilities", 13, "Theme tokens, arbitrary values and reusable patterns", "Build consistent designs without overusing magic numbers.", "In v4, @theme defines custom variables such as --color-pathway-600 and --font-display, which create corresponding utilities. Use predefined scales first; use an arbitrary value like w-[17rem] only for a specific justified need. Component extraction is useful when repeated markup represents one conceptual UI element. Keep classes as full detectable strings; dynamically concatenating bg-${color}-500 may fail class detection.", "@import \"tailwindcss\";\n@theme { --color-pathway-600: #167f64; --font-display: Inter, sans-serif; }\n<button class=\"bg-pathway-600 font-display\">Start</button>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-14", "Utilities", 14, "Dark mode, source scanning, and production output", "Understand when utilities are generated and how theme variants work.", "Tailwind finds complete class names in source files and emits a production CSS asset, not runtime JavaScript style rules. Default dark: follows prefers-color-scheme; for a manual toggle configure @custom-variant dark (&:where(.dark, .dark *)); then apply the dark class to an ancestor. Keep generated classes discoverable in real source or explicitly define permitted alternatives. Check npm run build for production behavior.", "@custom-variant dark (&:where(.dark, .dark *));\n<article class=\"bg-white text-slate-900 dark:bg-slate-900 dark:text-white\">...</article>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-15", "Project: Recreate Pathway", 15, "Read the real interface and plan components", "Rebuild the application the learner is currently using as a separate practice app.", "Open https://pathway.orangecastle.net and inspect its course sidebar, top header, breadcrumb/navigation, lesson title, instructional notes, code examples, progress state and Continue/Back actions. In browser DevTools measure desktop and narrow viewport behavior. Do not copy private application data or assume a screenshot captures accessibility. Draw a component map: AppShell, CourseSidebar, TopBar, LessonHeader, LessonNotes, CodeExample and LessonNavigation.", "Pathway shell\n├─ CourseSidebar (course groups + active lesson)\n└─ Main\n   ├─ TopBar\n   ├─ LessonHeader\n   ├─ LessonNotes\n   ├─ CodeExample\n   └─ LessonNavigation", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-16", "Project: Recreate Pathway", 16, "Build the shell, sidebar and header", "Create the same responsive information architecture using Tailwind utilities.", "In the practice Vite app, create a sidebar and main landmark. Keep the sidebar visible at larger widths and provide a labeled menu button for narrow screens; wire its visibility to React state. Use grid for the shell, flex for header actions and a max-width inner content column. Give the currently selected lesson aria-current='page'. Start from real Pathway labels but use mock course data.", "<div className=\"grid min-h-screen bg-slate-50 md:grid-cols-[16rem_minmax(0,1fr)]\"><aside className=\"hidden border-r bg-white p-4 md:block\" aria-label=\"Course navigation\">...</aside><main className=\"min-w-0\"><header className=\"border-b bg-white px-6 py-4\">Pathway</header><div className=\"mx-auto max-w-4xl p-6\">...</div></main></div>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-17", "Project: Recreate Pathway", 17, "Style the lesson content and interactions", "Recreate Pathway's cards, typography, navigation and active states with accessible controls.", "Implement a lesson header, introductory paragraphs, bullet list, code block, progress label, Back and Continue buttons. Use overflow-x-auto on code samples, semantic pre/code, list markup for study bullets, and visible focus styles on every action. Extract repeated card/button patterns into React components rather than repeating long strings. Keep active state and disabled navigation meaningful, not merely decorative.", "<section className=\"rounded-xl border bg-white p-6 shadow-sm\"><h2 className=\"text-lg font-semibold\">Lesson Notes</h2><ul className=\"mt-3 list-disc space-y-2 pl-5 text-emerald-700\"><li>Understand utilities</li></ul></section>", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-18", "Project: Recreate Pathway", 18, "Responsive polish, dark theme and quality audit", "Verify that your reconstruction holds up in real use and explain tradeoffs.", "Test widths around 320px, 768px and desktop; verify keyboard-only access, headings in order, active navigation announcements, focus-visible rings, color contrast, text zoom and horizontal scrolling only inside code. Optionally add a dark theme toggle, theme tokens and component extraction. Run npm run build. Compare your page next to the live Pathway UI and write down where custom CSS is simpler than utilities.", "Checklist: shell + nav + lesson + code + Back/Continue; narrow screen; keyboard access; contrast; production build.", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs),
        new("tailwind-19", "Project: Recreate Pathway", 19, "Final walkthrough and design review", "Demonstrate independent Tailwind reasoning, not memorized class strings.", "Present the finished Pathway-inspired lesson screen at both narrow and wide widths. Explain how grid creates the shell, flex aligns actions, spacing utilities correspond to the box model, variants cover states, and tokens prevent drift. Identify two strengths and two weaknesses you actually observed. Extend one screen on your own and compare computed CSS in DevTools. Keep this a practice clone: do not replace Pathway's live CSS during the exercise.", "Deliverables: running local Vite app, component tree, responsive screenshots, keyboard checklist and written design tradeoffs.", new Exercise(ExerciseKind.Presentation, "Practice and reflect", "Apply this lesson in your local practice project before continuing.", ["Inspect generated CSS in DevTools", "Try the example in your editor", "Explain the underlying CSS concept"], null, null, [], "Review the example and practice locally.", []), null, TailwindDocs)
